function area(r) {
  return Math.max(0, r.maxX - r.minX) * Math.max(0, r.maxY - r.minY);
}

function enlarge(r, obj) {
  return {
    minX: Math.min(r.minX, obj.minX),
    minY: Math.min(r.minY, obj.minY),
    maxX: Math.max(r.maxX, obj.maxX),
    maxY: Math.max(r.maxY, obj.maxY),
  };
}

function enlargementNeeded(r, obj) {
  return area(enlarge(r, obj)) - area(r);
}

function overlaps(a, b) {
  return a.minX <= b.maxX && a.maxX >= b.minX &&
         a.minY <= b.maxY && a.maxY >= b.minY;
}

