class RTreeNode {
  constructor(isLeaf, maxEntries = 4) {
    this.isLeaf = isLeaf;
    this.maxEntries = maxEntries;
    this.entries = []; // { mbr, data } for leaves, { mbr, child } for internal nodes
    this.mbr = null;
  }

  insert(entry) {
    if (this.isLeaf) {
      this.entries.push(entry);
    } else {
      const best = this.entries.reduce((a, b) =>
        enlargementNeeded(a.mbr, entry.mbr) <= enlargementNeeded(b.mbr, entry.mbr) ? a : b
      );
      best.child.insert(entry);
      best.mbr = enlarge(best.mbr, entry.mbr);
    }
    if (this.entries.length > this.maxEntries) this.split();
  }

  search(query, found = []) {
    for (const e of this.entries) {
      if (!overlaps(e.mbr, query)) continue; // skip non overlapping subtree entirely
      if (this.isLeaf) found.push(e.data);
      else e.child.search(query, found);
    }
    return found;
  }
}

